INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('light-crusader', 15073, '1995-05-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ghs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar30jl.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Light Crusader', 'Fight your way through a dungeon of evil! Innocent people are vanishing victims of horrifying magic. You a master swordsman are challenged to save them! Only your sword and razor sharp mind will help you survive the lethal labyrinth rescue the people and save the kingdom! Brutal real time arcade style fighting against legions of gruesome and deadly dungeon monsters! Incredible 3-D graphics make the action real! Solve intricate 3-D puzzles or perish! Save up to four games so you can fully explore the expansive playing environment.' FROM games WHERE igdb_id = 15073 ON CONFLICT (game_id, language_code) DO NOTHING;
