INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rayman', 'Rayman is a side-scrolling platformer starring the titular Rayman, a big-nosed chap with no arms or legs. Rayman can jump and use his hair to hover for a short period of time. He can also attack by throwing his fists, or winding up his fists for a more powerful punch. He can occasionally find special power ups that grant him unlimited flying power, giving him the ability to navigate through tricky mazes.' FROM games WHERE igdb_id = 1963 ON CONFLICT (game_id, language_code) DO NOTHING;
