INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prehistorik Man', 'In a small prehistoric village, disaster has struck! The winter food store has been eaten by greedy dinosaurs and the villagers are facing starvation! The Village Chief has chosen Sam to save mankind by leading a quest to find the legendary Dinosaur Graveyard. Sam must cross many unfamed prehistorik lands and bring back enough valuable bones to buy all the food the villagers need to survive the winter.' FROM games WHERE igdb_id = 49030 ON CONFLICT (game_id, language_code) DO NOTHING;
