INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Mortal Kombat 3', 'Ultimate Mortal Kombat 3 combines the best of all the Mortal Kombats into a single cartridge. 23 playable characters are immediately available, such as Reptile, Cyrax, Scorpion, Sub-Zero, Jax, Katana, Sonya, and more. There are two bosses that are unlockable, as well as additional characters and a variety of new levels, some of which are interactive. Players can go against the computer one-on-one, two-on-two, or take part in the 8-fighter tournament.' FROM games WHERE igdb_id = 1621 ON CONFLICT (game_id, language_code) DO NOTHING;
