INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario''s Picross', 'Mario''s Picross is a puzzle game for the Game Boy and the first game in the Nintendo-published Picross series. In this game, Mario takes on the role of an archaeologist who chisels away the squares in each playfield. The result is a small picture. There are 256 different puzzles to solve, divided into four courses with increasing difficulty level.' FROM games WHERE igdb_id = 71976 ON CONFLICT (game_id, language_code) DO NOTHING;
