INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simon the Sorcerer II: The Lion, the Wizard and the Wardrobe', 'The Evil wizard Sordid is brought back to life when a magic-book of his is set ablaze and thrown into the middle of a chalkboard pentagram by the father of Runt, a young boy wanting to become a mighty sorcerer. Sordid promises him that he can become his apprentice if he helps him exact his vengeance on Simon.
