INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Pop''n', 'The game is a side-scroller which is divided into six stages. The player starts with a three-heart life gauge and one spell attack. The player can increase Princess''s lives by collecting golden tokens (which look like the Princess''s face), gaining one life for every three coins collected. The player can also increase health by finding heart containers in treasure chests. Spells can be obtained throughout the game and are important for advancing further.' FROM games WHERE igdb_id = 9671 ON CONFLICT (game_id, language_code) DO NOTHING;
