INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Sword and Fairy', 'The Legend of Sword and Fairy is a role-playing video game developed by the Taiwanese company Softstar Entertainment and its subsidiaries. The game incorporates elements of wuxia, shenmo and fantasy. Since its release in 1995, the game has spawned a successful video game franchise in Taiwan and mainland China. It was also adapted into the 2005 Chinese television series Chinese Paladin.' FROM games WHERE igdb_id = 18928 ON CONFLICT (game_id, language_code) DO NOTHING;
