INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Super Heroes', 'Marvel Super Heroes is a 2D fighting game and the second Capcom title to feature characters from the Marvel comic universe. Each character starts with a set of gems. These can be activated during a fight to improve speed, power and defence, or provide special abilities to create crushing stone walls, open up a rift in space, or reverse the opponent''s controls. The use of the gems is inspired by the The Infinity Gauntlet comic book series.' FROM games WHERE igdb_id = 27890 ON CONFLICT (game_id, language_code) DO NOTHING;
