INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: The Next Generation - A Final Unity', 'Star Trek: The Next Generation – A Final Unity is an adventure game by Spectrum HoloByte, based on the Star Trek universe. It puts the player in control of Captain Picard and his crew of the Enterprise D and features traditional point-and-click adventure gameplay as well as free-form space exploration, diplomatic encounters and tactical ship-to-ship combat.
