INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loaded', 'Loaded is a violent, bloody top-down shooter which places you in the boots of one of six characters, who are all strange and deformed, from a psychotic clown to a huge baby. Loaded is a mission based game, where you have to complete various objectives, such as "escape the prison." Throughout each mission, there are tons of enemies to kill. You can choose to play through the single player campaign, or you can go head to head in two player.' FROM games WHERE igdb_id = 18682 ON CONFLICT (game_id, language_code) DO NOTHING;
