INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flight of the Amazon Queen', 'Flight of the Amazon Queen follows a pilot for hire named Joe King who is hired to fly a famous actress to her next job, but ends up in a lightning storm and crashes deep in the Amazon Jungle. In the jungle, Joe uncovers a plot by a mad scientist to take over the world by creating an army of dinosaur women created from Amazon women.' FROM games WHERE igdb_id = 8789 ON CONFLICT (game_id, language_code) DO NOTHING;
