INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astérix and the Power of the Gods', 'Emperor Caesar''s forces have stolen the legendary shield of Vercingetorix and it is Asterix and Obelix''s mission to return it to the Gaulish village. Play as either character as your adventure takes you through over 20 levels, through Lutetia, Egypt, Alexandria and Mesopotamia on your way to Rome itself!' FROM games WHERE igdb_id = 19781 ON CONFLICT (game_id, language_code) DO NOTHING;
