INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chrono Trigger', 'In this turn-based Japanese RPG, young Crono must travel through time through a misfunctioning teleporter to rescue his misfortunate companion and take part in an intricate web of past and present perils. The adventure that ensues soon unveils an evil force set to destroy the world, triggering Crono''s race against time to change the course of history and bring about a brighter future.' FROM games WHERE igdb_id = 1802 ON CONFLICT (game_id, language_code) DO NOTHING;
