INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hong-kong-97', 9616, '1995-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2uwd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/irjqzbspexbstmgilgih.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hong Kong 97', 'Hong Kong 97 is a 1995 multidirectional shooter video game made in Japan for the Super Famicom in disk drive format by HappySoft Ltd., a homebrew game company. The game was designed by the Japanese game journalist Kowloon Kurosawa (クーロン黒沢), who said the game was made in about a week. The game has gained a cult following in Japan and Taiwan for its notoriously poor quality — it has been ranked as a kusoge, which literally means "shitty game", a game considered "so bad that it''s good". It has since been given multiple parody treatments.
