INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumping Flash!', 'Jumping Flash! is a platform video game published by Sony Computer Entertainment and developed by Exact Co., Ltd. and Ultra Co., Ltd for the PlayStation in 1995. The game follows the robotic rabbit named ''Robbit'' as he searches for the missing Jet Pods which were scattered by the game''s astrophysicist antagonist, Baron Aloha. The game is presented in a first-person perspective, in which Robbit must explore each world to retrieve all the hidden Jet Pods, stop Aloha, and save the world from desolate emptiness.' FROM games WHERE igdb_id = 7432 ON CONFLICT (game_id, language_code) DO NOTHING;
