INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mighty Morphin Power Rangers: The Fighting Edition', 'Get ready to rock your world with the Mighty Morphin Power Rangers Fighting Edition. A three mode, smashing, bashing, monster trashing no-holds barred slugfest. This one-on-one two player simultaneous fighting game features your favourite Power Zord and a host of evil meanies. The Thunder Megazord, the Shogun Megazord, the Ninja Megazord, Lord Zedd, Goldar, and many more compete for total galactic supremacy in the mother of all battles. When the dust clears, only one will remain standing - who will be crowned the mightiest, morphiest warrior in the universe?' FROM games WHERE igdb_id = 3287 ON CONFLICT (game_id, language_code) DO NOTHING;
