INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Qwirks', 'Qwirks is an English adaptation of Puyo Puyo (1992) for home computers licensed from Compile. Unlike Dr. Robotnik''s Mean Bean Machine, and Kirby''s Avalanche it does not involve the use of a particular license, instead featuring entirely original characters. The game was introduced by Alexey Pajitnov, the creator of Tetris.' FROM games WHERE igdb_id = 93398 ON CONFLICT (game_id, language_code) DO NOTHING;
