INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psychic Detective', 'This game is an innovative slant on the interactive movie. You''re Eric Fox, a psychic detective who can transmit his psychic self to others, to see through their eyes and hear through their ears. That way you can find out things about the case you couldn''t otherwise. The game has many different conclusions. It''s a dark story though, and most people might not want to play through again.' FROM games WHERE igdb_id = 4258 ON CONFLICT (game_id, language_code) DO NOTHING;
