INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jelly Boy', 'Jelly Boy is a 1995 Europe-exclusive action platformer video game developed by Probe Entertainment and published by Ocean Software for the Super Nintendo Entertainment System and Nintendo Game Boy. The game was released exclusively in Europe in March 1995. Jelly Boy was planned to be released on the Sega Genesis but was canceled.' FROM games WHERE igdb_id = 23858 ON CONFLICT (game_id, language_code) DO NOTHING;
