INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighting Vipers', 'Fighting Vipers is a 3D fighting video game created by Sega AM2. While it shares the game engine with AM2''s Virtua Fighter 2, it distinguishes itself with enclosed arenas and an armour mechanic. The game is primarily designed for Western audiences, incorporating a U.S. setting and embracing more freeform styles of martial arts.' FROM games WHERE igdb_id = 39471 ON CONFLICT (game_id, language_code) DO NOTHING;
