INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimIsle: Missions in the Rainforest', 'Pack your bags, have the neighbors collect your mail, and take a working vacation in the rainforests of SimIsle. Build tourist hotels, exploit natural resources and develop industry in a land of beauty and danger. Can you become wealthy and keep native populations, tourists, and industry leaders happy? Or will your actions destroy the delicate balance of a fragile ecosystem?' FROM games WHERE igdb_id = 12907 ON CONFLICT (game_id, language_code) DO NOTHING;
