INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Full Throttle', 'Full Throttle is a computer adventure game developed and published by LucasArts. It was designed by Tim Schafer, who would later go on to design Grim Fandango, Psychonauts and Brütal Legend. The game features voice actors Roy Conrad and Mark Hamill. It was released on April 30, 1995. It is the tenth game to use the SCUMM adventure game engine.' FROM games WHERE igdb_id = 180 ON CONFLICT (game_id, language_code) DO NOTHING;
