INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('addams-family-values--1', 5341, '1995-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co64ph.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sdvbscabixj4vrgvnsed.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Addams Family Values', 'Baby Pubert, the most recent addition to the Addams Family, has been abducted by Debbie Jellinski, his former nanny. As Uncle Fester it is your job to rescue little Pubert. You must search the surrounding areas (forests, swamps, gardens and the like) of Addams mansion, while avoiding traps, solving puzzles and killing monsters. You''ll face such hellish creatures as vultures, gargoyles, bats, ghosts and ghouls.
