INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('venom-slash-spider-man-separation-anxiety', 46182, '1995-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coal37.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc778m.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Venom/Spider-Man: Separation Anxiety', 'Separation Anxiety is a side scrolling beat''em up game, featuring characters and stories taken from the Spiderman comics. The story is loosely based on a mini series of comics about Venom. In this game, the player(s) gets to choose between controlling Spider-Man, or his on and off again foe Venom. As Spiderman you must stop the life foundation who have removed five symbiotes from Venom. They plan to bond them with their soldiers, creating a dangerous army. Venom recovering from his wounds also realises he must destroy them.
