INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Flight Simulator 5.1', 'Flight Simulator 5.1 add the ability to handle scenery libraries including wide use of satellite imagery, faster performance, and a barrage of weather effects: storms, 3D clouds, and fog became true-to-life elements in the Flight Simulator world. This edition was also the first version that was released on CD-ROM and the last for DOS.' FROM games WHERE igdb_id = 3358 ON CONFLICT (game_id, language_code) DO NOTHING;
