INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('foul-play-mystery-at-awkward-manor--1', 127783, '1995-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vfe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7gp4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foul Play - Mystery at Awkward Manor', 'Something terrible has happened at Awkward Manor! For all those who love a good murder mystery, here is a new twist. Now you can explore an elegant English mansion, just as if you were there in person. Forget virtual reality- Virtual Travel makes it real! There are ten different game levels to satisfy every age and ability. As a gumshoe detective at Level 1, you''ll get lots of help, but as a skilled detective at Level 10, it could take you an hour or more to solve each mystery! Awkward Manor has fourteen beautifully photographed rooms and thousands of places where suspects may have left clues... there''s a clue now, under that chair! It looks as if Major Gallop was in the library! When was he there? Ring for the butler, he may be able to help you... Oh well, not this time! Let''s go upstairs to the Royal Bedroom... Mrs. Thatcham''s there! She may know more about the Major''s movements! Let''s ask her where she was at 7.45... Yes! As she walks away, she says she was with Major Gallop in the Ballroom! Maybe he was in here as well! Make a thorough search and... What''s this above the wardrobe? Ah ha!, the murder weapon! Now we''re on the murderer''s trail! Who else was here?... Gallop! Again! It looks very bad indeed for the Major! The room, the weapon, the time, and finally- the Accusation! Gotcha! Now Sergeant Plod arrives to take him away! Shall we go on to a more difficult challenge? Yes! And next time you play, the mystery will be completely different. With over 4,000 different solutions, why not invite your friends over? Up to six players can take part- or you can solve the mystery yourself! The extensive on-line help and tutorial system is always just one click away. Much better than a manual, it actually shows you how the game works, and gives hints to help you solve each mystery. Virtual Travel incorporating over 5,000 color photographs. 14 Rooms: 7 Upstairs, 7 Downstairs. Over 2,000 sounds. Thousands of clue locations.' FROM games WHERE igdb_id = 127783 ON CONFLICT (game_id, language_code) DO NOTHING;
