INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ridge Racer Revolution', 'Ridge Racer Revolution is the PlayStation sequel of Ridge Racer. Like the original Ridge Racer, the player races against eleven other computer-controlled cars. The game adds two hidden cars for the player to unlock, and 2-player support.' FROM games WHERE igdb_id = 18697 ON CONFLICT (game_id, language_code) DO NOTHING;
