INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marsupilami', 'Marsupilami is a character created by Belgian cartoonist "Franquin". Marsupilami is a long tailed made-up character who was stolen from the jungle and performs in a circus. After helping the other animals escape, Marsupilami must make his way back to the country he came from - Palombia.
