INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Rash 3', 'The Rash is back in the latest, nastiest, baddest race game for your Genesis. This time there''s five NEW weapons, including the cattle-prod and crow bar. NEW race tracks take you across the globe, from the Aussie Outback to nighttime urban Japan. NEW modes raise the ante with the other Rashers while the NEW digitized graphics and interactive obstacles charge NEW life into the gameplay!' FROM games WHERE igdb_id = 45592 ON CONFLICT (game_id, language_code) DO NOTHING;
