INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Icebreaker', 'Icebreaker is a puzzle/shooter that has the player take control of a flying pyramid who has to navigate through 150 levels blasting other stationary pyramids. The stationary pyramids are either green, blue or red and can turn into each others colors throughout a level. The red pyramids can be destroyed by being shot, the blue pyramids are destroyed by being touched, and the green pyramids are destroyed by luring enemy pyramids into them.' FROM games WHERE igdb_id = 4332 ON CONFLICT (game_id, language_code) DO NOTHING;
