INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Sidekicks 3: The Next Glory', 'Loaded with world class excitement! Features 6 competition modes like World Cup for 64 worldwide teams. Utilizes Digitized Trace Animation and 3D camera angled shots for a realistic on-the-fly action graphic explosion. With 8 different playing modes including options such as Speed and Stamina, you can mix and match 512 different team configurations. Accidents hinder or enhance a team''s ability within head-to-head gameplay for the ultimate super-real soccer experience!' FROM games WHERE igdb_id = 39332 ON CONFLICT (game_id, language_code) DO NOTHING;
