INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Fighter Alpha: Warriors'' Dreams', 'Street Fighter Alpha: Warriors'' Dreams was the first all new Street Fighter game produced by Capcom since the release of Street Fighter II. It introduces several new features, expanding on the Super Combo system previously featured in Super Street Fighter II Turbo with graphics drawn in the same animated style Capcom employed in Darkstalkers. Street Fighter Alpha revamps the Super Combo system introduced in Super Street Fighter II Turbo by adding a three-level Super Combo gauge that fills in as the player performs regular and special moves.' FROM games WHERE igdb_id = 6702 ON CONFLICT (game_id, language_code) DO NOTHING;
