INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Phantasia', 'Tales of Phantasia is the first installment of the Tales series, and was released by Namco in 1995 for the Super Famicom. Released at the end of 1995, Tales of Phantasia is considered one of the crowning achievements for its time. It has graphics that push the console to its limits, an original never-before-seen battle system, and the addition of actual voices and voice actors. It is also the first and only Super Famicom game to feature an entirely original, vocalized theme song featured directly in the game.' FROM games WHERE igdb_id = 1200 ON CONFLICT (game_id, language_code) DO NOTHING;
